import {readFileSync,writeFileSync} from 'node:fs';import {createHash} from 'node:crypto';
import {LocalModelCache,localExtractionKey} from '../../../src/analyze/local-model-cache.ts';import {sectionDescriptor,channelTopology} from '../../../src/analyze/segmented-channel.ts';
const path=process.argv[2],id=JSON.parse(readFileSync(path+'/identity.json','utf8')),plan=JSON.parse(readFileSync(path+'/plan-0.125.json','utf8')),cache=new LocalModelCache(path+'/cache');
const read=(key:string)=>{const e=JSON.parse(readFileSync(path+'/cache/'+key+'.json','utf8'));if(createHash('sha256').update(e.payload).digest('hex')!==e.checksum)throw Error('Cache checksum');return JSON.parse(e.payload);};
const keys:string[]=[];const instances=plan.blocks.map((b:any)=>{let data:any,key:string;if(b.kind==='local'){key=localExtractionKey(cache,id.core,{boardJson:b.boardJson,geometry:b.geometry,magneticPatchLevel:b.magneticPatchLevel,bandHz:[1000,100000]});const p=read(key);data=p.candidate.model;}else{key=cache.key({core:id.core,kind:'section-v3',request:{line:b.line,mesh:b.mesh,frequencies:id.frequencies}});const p=read(key);data=sectionDescriptor(p.parameters,b.line,id.frequencies,b.dcConductors);}keys.push(key);const ports=b.cuts.map((_:any,i:number)=>'port-'+i);return {id:b.id,model:{id:b.id,kind:'network',ports,data},ports};});
const t=channelTopology(plan),request={instances,...t,frequencies:id.frequencies,representation:'S',referenceOhm:plan.ports.map(()=>50),budget:{maxSeconds:30,maxMemoryMiB:1024}};writeFileSync(path+'/minimal-assembly-request.json',JSON.stringify(request));writeFileSync(path+'/cache-model-provenance.json',JSON.stringify({core:id.core,keys,boardSha256:id.boardSha256,sectionOwnership:plan.blocks.map((b:any)=>({id:b.id,kind:b.kind,ownership:b.ownership})),requestSha256:createHash('sha256').update(JSON.stringify(request)).digest('hex')}));console.log(JSON.stringify({blocks:instances.map((i:any)=>({id:i.id,states:i.model.data.potentialNodes.length+i.model.data.currentDofs.length,ports:i.ports.length})),bytes:JSON.stringify(request).length}));
